#!/usr/bin/env python3
from __future__ import annotations
import argparse, json, sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
REG=ROOT/'registry/navy18.json'; CAT=ROOT/'registry/naval_catalog.json'
SGUI=ROOT/'common/scripted_guis/cmp_navy18_ship_control_sgui.txt'
EFFECT=ROOT/'common/scripted_effects/cmp_navy18_ship_control_effects.txt'
LOC_RU=ROOT/'localization/russian/cmp_navy18_ship_control_l_russian.yml'
LOC_EN=ROOT/'localization/english/cmp_navy18_ship_control_l_english.yml'
HEADER='# AUTO-GENERATED by tools/generate_navy18_ship_control.py. DO NOT EDIT BY HAND.\n'

def load(): return json.loads(REG.read_text(encoding='utf-8')), json.loads(CAT.read_text(encoding='utf-8'))

def selected_ship_limit(extra: list[str]|None=None) -> str:
    bits=['has_variable = cmp_navy18_exact_ship_target']+(extra or [])
    return ' '.join(bits)

def allowed_flagship_or(cat:dict)->str:
    hulls=[h for h in cat['combat_hulls'] if h.get('can_be_flagship')]
    return 'OR = { ' + ' '.join(f"is_ship_type = ship_type:{h['ship_type']}" for h in hulls) + ' }'

def generate_sgui(cfg,cat):
    sc=cfg['ship_control']; max_slots=sc['max_slots']; allow=allowed_flagship_or(cat)
    L=[HEADER.rstrip(),'# beta18-pre4 exact ship selector: formation root -> ordered non-destroyed ship -> persistent marker on ship scope.']
    L += [
      'cmp_navy18_shipctrl_has_ship = { scope = military_formation is_shown = { owner = { is_player = yes } any_scope_ship = { has_variable = cmp_navy18_exact_ship_target } } }',
      'cmp_navy18_shipctrl_target_lost = { scope = military_formation is_shown = { owner = { is_player = yes } has_variable = cmp_navy18_exact_ship_slot NOT = { any_scope_ship = { has_variable = cmp_navy18_exact_ship_target } } } }',
      'cmp_navy18_shipctrl_clear = { scope = military_formation is_valid = { owner = { is_player = yes } } effect = { cmp_navy18_shipctrl_clear_effect = yes } }',
    ]
    for n in range(1,max_slots+1):
        L.append(f'cmp_navy18_shipctrl_slot_{n}_available = {{ scope = military_formation is_shown = {{ owner = {{ is_player = yes }} num_non_destroyed_ships >= {n} }} }}')
        L.append(f'cmp_navy18_shipctrl_slot_{n}_selected = {{ scope = military_formation is_shown = {{ var:cmp_navy18_exact_ship_slot = {n} any_scope_ship = {{ has_variable = cmp_navy18_exact_ship_target }} }} }}')
        L.append(f'cmp_navy18_shipctrl_select_slot_{n} = {{ scope = military_formation is_valid = {{ owner = {{ is_player = yes }} num_non_destroyed_ships >= {n} }} effect = {{ cmp_navy18_shipctrl_select_slot_{n}_effect = yes }} }}')
    for h in cat['combat_hulls']:
        L.append(f"cmp_navy18_shipctrl_type_{h['id']} = {{ scope = military_formation is_shown = {{ any_scope_ship = {{ has_variable = cmp_navy18_exact_ship_target is_ship_type = ship_type:{h['ship_type']} }} }} }}")
    states={
      'flagship':'is_flagship = yes','not_flagship':'NOT = { is_flagship = yes }',
      'damaged':'is_damaged = yes','healthy':'NOT = { is_damaged = yes }',
      'in_port':'is_in_port = yes','at_sea':'NOT = { is_in_port = yes }',
      'in_battle':'is_in_battle = yes','not_in_battle':'NOT = { is_in_battle = yes }',
    }
    for sid,expr in states.items():
        L.append(f'cmp_navy18_shipctrl_{sid} = {{ scope = military_formation is_shown = {{ any_scope_ship = {{ has_variable = cmp_navy18_exact_ship_target {expr} }} }} }}')
    # Human-readable health/crew bands; exact numeric values stay native until a proven GUI ship accessor is available.
    bands=[('excellent',0.75,None),('worn',0.50,0.75),('critical',0.25,0.50),('near_loss',0.0,0.25)]
    for metric in ['hit_points_percent','crew_percent']:
        prefix='hp' if metric.startswith('hit') else 'crew'
        for name,lo,hi in bands:
            cond=f'{metric} >= {lo}'
            if hi is not None: cond += f' NOT = {{ {metric} >= {hi} }}'
            L.append(f'cmp_navy18_shipctrl_{prefix}_{name} = {{ scope = military_formation is_shown = {{ any_scope_ship = {{ has_variable = cmp_navy18_exact_ship_target {cond} }} }} }}')
    L += [
      f'cmp_navy18_shipctrl_can_set_flagship = {{ scope = military_formation is_shown = {{ owner = {{ is_player = yes }} any_scope_ship = {{ {selected_ship_limit(["NOT = { is_in_battle = yes }", "NOT = { is_flagship = yes }", allow])} }} }} }}',
      'cmp_navy18_shipctrl_can_unset_flagship = { scope = military_formation is_shown = { owner = { is_player = yes } any_scope_ship = { has_variable = cmp_navy18_exact_ship_target NOT = { is_in_battle = yes } is_flagship = yes } } }',
      f'cmp_navy18_shipctrl_set_flagship = {{ scope = military_formation is_valid = {{ owner = {{ is_player = yes }} any_scope_ship = {{ {selected_ship_limit(["NOT = { is_in_battle = yes }", "NOT = { is_flagship = yes }", allow])} }} }} effect = {{ cmp_navy18_shipctrl_set_flagship_effect = yes }} }}',
      'cmp_navy18_shipctrl_unset_flagship = { scope = military_formation is_valid = { owner = { is_player = yes } any_scope_ship = { has_variable = cmp_navy18_exact_ship_target NOT = { is_in_battle = yes } is_flagship = yes } } effect = { cmp_navy18_shipctrl_unset_flagship_effect = yes } }',
      'cmp_navy18_shipctrl_result_selected = { scope = military_formation is_shown = { var:cmp_navy18_shipctrl_result = 1 } }',
      'cmp_navy18_shipctrl_result_flagship_set = { scope = military_formation is_shown = { var:cmp_navy18_shipctrl_result = 2 } }',
      'cmp_navy18_shipctrl_result_flagship_unset = { scope = military_formation is_shown = { var:cmp_navy18_shipctrl_result = 3 } }',''
    ]
    return '\n'.join(L)

def generate_effects(cfg,cat):
    sc=cfg['ship_control']; max_slots=sc['max_slots']; allow=allowed_flagship_or(cat)
    L=[HEADER.rstrip(),'# Marker persists on the exact ship object. Fleet selection remains Victoria-native and marker-free.']
    L += [
      'cmp_navy18_shipctrl_clear_owner_marks_effect = {',
      '    owner = {',
      '        every_scope_fleet = {',
      '            remove_variable = cmp_navy18_exact_ship_slot',
      '            remove_variable = cmp_navy18_shipctrl_result',
      '            every_scope_ship = { remove_variable = cmp_navy18_exact_ship_target }',
      '        }',
      '    }',
      '}',
      'cmp_navy18_shipctrl_clear_effect = { cmp_navy18_shipctrl_clear_owner_marks_effect = yes }',
    ]
    for n in range(1,max_slots+1):
        L += [
          f'cmp_navy18_shipctrl_select_slot_{n}_effect = {{',
          '    cmp_navy18_shipctrl_clear_owner_marks_effect = yes',
          f'    set_variable = {{ name = cmp_navy18_exact_ship_slot value = {n} }}',
          '    ordered_scope_ship = {',
          '        limit = { hit_points > 0 }',
          '        order_by = power_projection',
          f'        position = {n-1}',
          '        check_range_bounds = no',
          '        set_variable = cmp_navy18_exact_ship_target',
          '    }',
          '    if = { limit = { any_scope_ship = { has_variable = cmp_navy18_exact_ship_target } } set_variable = { name = cmp_navy18_shipctrl_result value = 1 } }',
          '}',
        ]
    L += [
      'cmp_navy18_shipctrl_set_flagship_effect = {',
      '    every_scope_ship = {',
      f'        limit = {{ has_variable = cmp_navy18_exact_ship_target NOT = {{ is_in_battle = yes }} NOT = {{ is_flagship = yes }} {allow} }}',
      '        set_as_flagship = yes',
      '    }',
      '    set_variable = { name = cmp_navy18_shipctrl_result value = 2 }',
      '}',
      'cmp_navy18_shipctrl_unset_flagship_effect = {',
      '    every_scope_ship = {',
      '        limit = { has_variable = cmp_navy18_exact_ship_target NOT = { is_in_battle = yes } is_flagship = yes }',
      '        set_as_flagship = no',
      '    }',
      '    set_variable = { name = cmp_navy18_shipctrl_result value = 3 }',
      '}',''
    ]
    return '\n'.join(L)

def generate_loc(cfg,cat,lang):
    ru=lang=='russian'; L=['l_russian:' if ru else 'l_english:']; add=lambda k,v:L.append(f' {k}:0 "{v}"')
    if ru:
      vals={
      'CMP_NAVY18_MODE_SHIPCTRL':'КОРАБЛИ','CMP_NAVY18_SHIPCTRL_TITLE':'Точный контроль кораблей','CMP_NAVY18_SHIPCTRL_DESC':'Выберите флот штатным механизмом Victoria 3, затем выберите конкретный корабль по позиции в текущем списке. После выбора точная метка хранится на объекте Ship и не зависит от повторного поиска флота.','CMP_NAVY18_SHIPCTRL_ORDER_NOTE':'Позиции 1–100 сортируются по демонстрации силы среди неуничтоженных кораблей. После выбора метка закрепляется за конкретным кораблём; изменение порядка не меняет уже выбранную цель.','CMP_NAVY18_SHIPCTRL_SELECT_FLEET_FIRST':'Сначала выберите флот через «Выбрать / изменить флот».','CMP_NAVY18_SHIPCTRL_PAGE':'Страница кораблей','CMP_NAVY18_SHIPCTRL_SLOT_TT':'Выбрать точный корабль в текущем порядке флота. Недоступные позиции означают, что во флоте меньше неуничтоженных кораблей.','CMP_NAVY18_SHIPCTRL_SELECTED':'Выбранный корабль','CMP_NAVY18_SHIPCTRL_NONE':'Корабль не выбран','CMP_NAVY18_SHIPCTRL_LOST':'Выбранная цель больше не существует — выберите корабль заново.','CMP_NAVY18_SHIPCTRL_TYPE':'Тип:','CMP_NAVY18_SHIPCTRL_STATUS':'Состояние','CMP_NAVY18_SHIPCTRL_FLAGSHIP':'#P Флагман#!','CMP_NAVY18_SHIPCTRL_NOT_FLAGSHIP':'Не флагман','CMP_NAVY18_SHIPCTRL_DAMAGED':'#N Повреждён#!','CMP_NAVY18_SHIPCTRL_HEALTHY':'#P Корпус исправен#!','CMP_NAVY18_SHIPCTRL_IN_PORT':'В порту','CMP_NAVY18_SHIPCTRL_AT_SEA':'В море','CMP_NAVY18_SHIPCTRL_IN_BATTLE':'#N В бою#!','CMP_NAVY18_SHIPCTRL_NOT_IN_BATTLE':'Вне боя','CMP_NAVY18_SHIPCTRL_HP_EXCELLENT':'Корпус: 75–100%','CMP_NAVY18_SHIPCTRL_HP_WORN':'Корпус: 50–75%','CMP_NAVY18_SHIPCTRL_HP_CRITICAL':'Корпус: 25–50%','CMP_NAVY18_SHIPCTRL_HP_NEAR_LOSS':'Корпус: менее 25%','CMP_NAVY18_SHIPCTRL_CREW_EXCELLENT':'Экипаж: 75–100%','CMP_NAVY18_SHIPCTRL_CREW_WORN':'Экипаж: 50–75%','CMP_NAVY18_SHIPCTRL_CREW_CRITICAL':'Экипаж: 25–50%','CMP_NAVY18_SHIPCTRL_CREW_NEAR_LOSS':'Экипаж: менее 25%','CMP_NAVY18_SHIPCTRL_SET_FLAGSHIP':'НАЗНАЧИТЬ ФЛАГМАНОМ','CMP_NAVY18_SHIPCTRL_UNSET_FLAGSHIP':'СНЯТЬ ФЛАГМАН','CMP_NAVY18_SHIPCTRL_FLAGSHIP_TT':'Изменяет флагман только для точно выбранного корабля. Корабль в бою или тип, которому запрещена роль флагмана, блокирует действие.','CMP_NAVY18_SHIPCTRL_CLEAR':'Сбросить выбор корабля','CMP_NAVY18_SHIPCTRL_CLEAR_TT':'Удаляет временную точную метку корабля у флотов державы игрока.','CMP_NAVY18_SHIPCTRL_RESULT_SELECTED':'#P Точный корабль выбран#!','CMP_NAVY18_SHIPCTRL_RESULT_FLAGSHIP_SET':'#P Корабль назначен флагманом#!','CMP_NAVY18_SHIPCTRL_RESULT_FLAGSHIP_UNSET':'#P Статус флагмана снят#!','CMP_NAVY18_SHIPCTRL_SCOPE_NOTE':'beta18 Final: точный выбор Ship и операции флагмана подтверждены полным регрессионным прогоном. Разрушающие операции с корпусом и экипажем по-прежнему не добавляются.'}
    else:
      vals={
      'CMP_NAVY18_MODE_SHIPCTRL':'SHIPS','CMP_NAVY18_SHIPCTRL_TITLE':'Exact Ship Control','CMP_NAVY18_SHIPCTRL_DESC':'Select a fleet through Victoria 3 native flow, then select an exact ship by its position in the current fleet ordering. The exact marker is stored on the Ship object and does not depend on resolving the fleet again.','CMP_NAVY18_SHIPCTRL_ORDER_NOTE':'Slots 1–100 are ordered by power projection among non-destroyed ships. Once selected, the marker stays on that exact Ship even if ordering changes.','CMP_NAVY18_SHIPCTRL_SELECT_FLEET_FIRST':'Select a fleet first using Select / change fleet.','CMP_NAVY18_SHIPCTRL_PAGE':'Ship page','CMP_NAVY18_SHIPCTRL_SLOT_TT':'Select the exact ship at this position. Disabled positions mean the fleet has fewer non-destroyed ships.','CMP_NAVY18_SHIPCTRL_SELECTED':'Selected ship','CMP_NAVY18_SHIPCTRL_NONE':'No ship selected','CMP_NAVY18_SHIPCTRL_LOST':'The selected ship no longer exists — select another ship.','CMP_NAVY18_SHIPCTRL_TYPE':'Type:','CMP_NAVY18_SHIPCTRL_STATUS':'Status','CMP_NAVY18_SHIPCTRL_FLAGSHIP':'#P Flagship#!','CMP_NAVY18_SHIPCTRL_NOT_FLAGSHIP':'Not flagship','CMP_NAVY18_SHIPCTRL_DAMAGED':'#N Damaged#!','CMP_NAVY18_SHIPCTRL_HEALTHY':'#P Hull healthy#!','CMP_NAVY18_SHIPCTRL_IN_PORT':'In port','CMP_NAVY18_SHIPCTRL_AT_SEA':'At sea','CMP_NAVY18_SHIPCTRL_IN_BATTLE':'#N In battle#!','CMP_NAVY18_SHIPCTRL_NOT_IN_BATTLE':'Out of battle','CMP_NAVY18_SHIPCTRL_HP_EXCELLENT':'Hull: 75–100%','CMP_NAVY18_SHIPCTRL_HP_WORN':'Hull: 50–75%','CMP_NAVY18_SHIPCTRL_HP_CRITICAL':'Hull: 25–50%','CMP_NAVY18_SHIPCTRL_HP_NEAR_LOSS':'Hull: below 25%','CMP_NAVY18_SHIPCTRL_CREW_EXCELLENT':'Crew: 75–100%','CMP_NAVY18_SHIPCTRL_CREW_WORN':'Crew: 50–75%','CMP_NAVY18_SHIPCTRL_CREW_CRITICAL':'Crew: 25–50%','CMP_NAVY18_SHIPCTRL_CREW_NEAR_LOSS':'Crew: below 25%','CMP_NAVY18_SHIPCTRL_SET_FLAGSHIP':'SET AS FLAGSHIP','CMP_NAVY18_SHIPCTRL_UNSET_FLAGSHIP':'UNSET FLAGSHIP','CMP_NAVY18_SHIPCTRL_FLAGSHIP_TT':'Changes flagship state only for the exact selected ship. Ships in battle or hulls that cannot be flagships block the action.','CMP_NAVY18_SHIPCTRL_CLEAR':'Clear ship selection','CMP_NAVY18_SHIPCTRL_CLEAR_TT':'Clears the temporary exact-ship marker from player fleets.','CMP_NAVY18_SHIPCTRL_RESULT_SELECTED':'#P Exact ship selected#!','CMP_NAVY18_SHIPCTRL_RESULT_FLAGSHIP_SET':'#P Ship assigned as flagship#!','CMP_NAVY18_SHIPCTRL_RESULT_FLAGSHIP_UNSET':'#P Flagship status removed#!','CMP_NAVY18_SHIPCTRL_SCOPE_NOTE':'beta18 Final: exact Ship targeting and flagship operations passed the full Navy regression. Destructive hull and crew writes remain intentionally unavailable.'}
    for k,v in vals.items(): add(k,v)
    for p in range(1,(cfg['ship_control']['max_slots']//cfg['ship_control']['page_size'])+1): add(f'CMP_NAVY18_SHIPCTRL_PAGE_{p}',str(p))
    for n in range(1,cfg['ship_control']['max_slots']+1): add(f'CMP_NAVY18_SHIPCTRL_SLOT_{n}',str(n))
    return '\n'.join(L)+'\n'

def outputs():
    cfg,cat=load(); return {SGUI:generate_sgui(cfg,cat),EFFECT:generate_effects(cfg,cat),LOC_RU:generate_loc(cfg,cat,'russian'),LOC_EN:generate_loc(cfg,cat,'english')}
def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--check',action='store_true'); a=ap.parse_args(); stale=[]
    for p,t in outputs().items():
        enc='utf-8-sig'
        if a.check:
            if not p.exists() or p.read_text(encoding=enc)!=t: stale.append(str(p.relative_to(ROOT)))
        else: p.parent.mkdir(parents=True,exist_ok=True); p.write_text(t,encoding=enc)
    if a.check:
        if stale: print('STALE: '+', '.join(stale),file=sys.stderr); return 1
        print('PASS: beta18 Final exact ship control codegen is deterministic'); return 0
    print('generated beta18 Final exact ship control SGUI/effects/localization'); return 0
if __name__=='__main__': raise SystemExit(main())
